import test from 'node:test';import assert from 'node:assert/strict';
import {newGame,save,restore} from './simulation.js';import {mapEventsAt} from './map-events.js';import {placeBackgrounds} from './place-backgrounds.js';import {locations} from './days.js';import {beginNeighborhoodEvent,resolveNeighborhoodEvent,neighborhoodEventView} from './neighborhood-events.js';import {communityActivityDefinitions} from './community-activities.js';
function afternoon(){const s=newGame();s.clock.minute=780;return s;}
test('all 30 destinations have their own distinct illustration tile',()=>{const tiles=Object.keys(locations).map(id=>{const b=placeBackgrounds[id];assert.ok(b,id);return `${b.set}:${b.index}`;});assert.equal(new Set(tiles).size,30);});
test('daily marker only appears during its window and disappears on completion without changing state',()=>{const s=afternoon();s.day=4;const original=save(s);assert.ok(mapEventsAt(s,'library').some(e=>e.kind==='daily'));assert.equal(save(s),original);s.fortnightLife={4:{done:true}};assert.ok(!mapEventsAt(s,'library').some(e=>e.kind==='daily'));s.fortnightLife={};s.clock.minute=700;assert.equal(mapEventsAt(s,'library').length,0);s.freeDay.home=true;s.clock.minute=800;assert.deepEqual(mapEventsAt(s,'library'),[]);});
test('public markers require personally read/heard information and never expose hidden NPCs',()=>{const s=afternoon(),d=communityActivityDefinitions['basketball-open'];assert.ok(!mapEventsAt(s,d.venue.location).some(e=>e.id==='basketball-open'));s.flow.postsRead={'basketball-open':true};assert.ok(mapEventsAt(s,d.venue.location).some(e=>e.id==='basketball-open'));assert.deepEqual(s.contacts,{});s.clock.minute=1080;assert.ok(!mapEventsAt(s,d.venue.location).some(e=>e.id==='basketball-open'));});
test('neighborhood marker leads to a real choice, time, information and persistent completion',()=>{let s=afternoon();s.location='pocketPark';assert.ok(mapEventsAt(s,'pocketPark').some(e=>e.id==='parkNote'));s=beginNeighborhoodEvent(s,'parkNote');s=restore(save(s));assert.equal(neighborhoodEventView(s).id,'parkNote');s=resolveNeighborhoodEvent(s,'help');assert.equal(s.clock.minute,795);assert.ok(s.known.includes('자취촌 공원 벤치 옆 물품 보관 안내'));assert.ok(!mapEventsAt(restore(save(s)),'pocketPark').some(e=>e.id==='parkNote'));assert.deepEqual(s.contacts,{});s.day=4;assert.ok(!mapEventsAt(s,'pocketPark').some(e=>e.id==='parkNote'));});
test('passing suppresses only today without rewards, stale place cannot resolve',()=>{let s=afternoon();s.location='pocketPark';s=beginNeighborhoodEvent(s,'parkNote');const elsewhere=structuredClone(s);elsewhere.location='busStop';assert.throws(()=>resolveNeighborhoodEvent(elsewhere,'help'));s=resolveNeighborhoodEvent(s,'pass');assert.equal(s.clock.minute,780);assert.equal(s.known.length,0);assert.ok(!mapEventsAt(s,'pocketPark').some(e=>e.id==='parkNote'));});
